import Foundation
import XCTest

/// Access to Tests/Fixtures (generated by `make fixtures`) and model availability.
enum Fixtures {
    static let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Fixtures")

    struct Fact: Decodable {
        let t: Double
        let fact: String
        let question: String
        let mustContain: [String]
        let speaker: String
    }
    struct Utterance: Decodable {
        let t0: Double
        let t1: Double
        let speaker: String
        let text: String
    }

    static func wav(_ name: String) throws -> URL {
        let url = root.appendingPathComponent("\(name).wav")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("\(name).wav missing — run make fixtures")
        }
        return url
    }
    static func facts(_ name: String) throws -> [Fact] {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(
            [Fact].self, from: Data(contentsOf: root.appendingPathComponent("\(name).facts.json")))
    }
    static func timeline(_ name: String) throws -> [Utterance] {
        try JSONDecoder().decode(
            [Utterance].self, from: Data(contentsOf: root.appendingPathComponent("\(name).timeline.json")))
    }
    static func script(_ name: String) throws -> String {
        try String(contentsOf: root.appendingPathComponent("scripts/\(name).txt"), encoding: .utf8)
    }
}

/// Word error rate with the same normalisation as tools/harness/wer.py: lower case, letters/digits only,
/// numbers 0–20 and tens spelled out.
enum WER {
    static let numbers: [String: String] = [
        "0": "zero", "1": "one", "2": "two", "3": "three", "4": "four", "5": "five", "6": "six", "7": "seven",
        "8": "eight",
        "9": "nine", "10": "ten", "11": "eleven", "12": "twelve", "13": "thirteen", "14": "fourteen", "15": "fifteen",
        "16": "sixteen", "17": "seventeen", "18": "eighteen", "19": "nineteen", "20": "twenty", "30": "thirty",
        "40": "forty", "50": "fifty", "60": "sixty", "70": "seventy", "80": "eighty", "90": "ninety",
    ]

    static func normalize(_ s: String) -> [String] {
        s.lowercased().replacingOccurrences(of: "'", with: "")
            .split { !$0.isLetter && !$0.isNumber }.map { numbers[String($0)] ?? String($0) }
    }

    static func rate(reference: String, hypothesis: String) -> Double {
        let r = normalize(reference)
        let h = normalize(hypothesis)
        guard !r.isEmpty else { return h.isEmpty ? 0 : 1 }
        var prev = Array(0...h.count)
        for i in 1...r.count {
            var cur = [i] + Array(repeating: 0, count: h.count)
            for j in stride(from: 1, through: h.count, by: 1) {
                cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] == h[j - 1] ? 0 : 1))
            }
            prev = cur
        }
        return Double(prev[h.count]) / Double(r.count)
    }
}
